using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class FitVacuumReservoir{
 static Vector3[] verts;static int[] triangles;
 static bool Inside(Vector3 p){var distances=new List<float>();for(int i=0;i<triangles.Length;i+=3){var a=verts[triangles[i]];var e1=verts[triangles[i+1]]-a;var e2=verts[triangles[i+2]]-a;var h=Vector3.Cross(Vector3.right,e2);float det=Vector3.Dot(e1,h);if(Mathf.Abs(det)<1e-9f)continue;float inv=1/det;var s=p-a;float u=inv*Vector3.Dot(s,h);if(u<0||u>1)continue;var q=Vector3.Cross(s,e1);float v=inv*q.x;if(v<0||u+v>1)continue;float d=inv*Vector3.Dot(e2,q);if(d>1e-6f&&!distances.Any(x=>Mathf.Abs(x-d)<.00001f))distances.Add(d);}return distances.Count%2==1;}
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var player=UnityEngine.Object.FindFirstObjectByType<PlayerController>();var tool=player.HeldInstrument.GetComponentsInChildren<VacuumTool>(true).Single(v=>v.name=="LVL_5");var f=tool.dustTray.GetComponent<MeshFilter>();var m=f.sharedMesh;var source=m.vertices;var t=m.GetTriangles(0);var parents=Enumerable.Range(0,source.Length).ToArray();Func<int,int> find=null;find=i=>parents[i]==i?i:parents[i]=find(parents[i]);var weld=new Dictionary<Vector3,int>();for(int i=0;i<source.Length;i++){if(weld.TryGetValue(source[i],out var n))parents[find(i)]=find(n);else weld[source[i]]=i;}for(int i=0;i<t.Length;i+=3){parents[find(t[i+1])]=find(t[i]);parents[find(t[i+2])]=find(t[i]);}
 var groups=t.Distinct().GroupBy(i=>find(i)).Select(g=>{var b=new Bounds(source[g.First()],Vector3.zero);foreach(var i in g)b.Encapsulate(source[i]);return new{id=g.Key,bounds=b};});var chamber=groups.Single(g=>g.bounds.size.x>.30f&&g.bounds.size.x<.34f&&g.bounds.size.y>.10f);
 var list=new List<int>();for(int i=0;i<t.Length;i+=3)if(find(t[i])==chamber.id){list.Add(t[i]);list.Add(t[i+1]);list.Add(t[i+2]);}triangles=list.ToArray();verts=source.Select(p=>tool.fillFrame.InverseTransformPoint(f.transform.TransformPoint(p))).ToArray();var bounds=new Bounds(verts[triangles[0]],Vector3.zero);foreach(var i in triangles)bounds.Encapsulate(verts[i]);
 float spacing=Mathf.Pow(bounds.size.x*bounds.size.y*bounds.size.z/1800f,1f/3f);float margin=spacing;var points=new List<Vector3>();var offsets=new[]{Vector3.zero,Vector3.left*margin,Vector3.right*margin,Vector3.up*margin,Vector3.down*margin,Vector3.forward*margin,Vector3.back*margin};
 var random=new System.Random(348);for(int attempt=0;attempt<24000&&points.Count<650;attempt++){var point=new Vector3(Mathf.Lerp(bounds.min.x+margin,bounds.max.x-margin,(float)random.NextDouble()),Mathf.Lerp(bounds.min.y+margin,bounds.max.y-margin,(float)random.NextDouble()),Mathf.Lerp(bounds.min.z+margin,bounds.max.z-margin,(float)random.NextDouble()));if(points.Any(p=>(p-point).sqrMagnitude<spacing*spacing*.52f))continue;if(offsets.All(o=>Inside(point+o)))points.Add(point);}

 if(points.Count<100)throw new Exception("Reservoir sampling failed: "+points.Count);
 Undo.RecordObject(tool,"Fit collected grain to casing");tool.reservoirPoints=points.ToArray();tool.reservoirSpacing=spacing;EditorUtility.SetDirty(tool);
 GameObject preview=null;int outside=0;try{preview=UnityEngine.Object.Instantiate(player.HeldInstrument.gameObject,player.HeldInstrument.parent);preview.name="Temporary fitted vacuum preview";preview.SetActive(true);foreach(Transform level in preview.transform.Find("Item In Hands"))level.gameObject.SetActive(level.name=="LVL_5");var shovel=preview.GetComponent<ShovelTool>();shovel.Cargo.Add(GrainType.Corn,shovel.CapacityKg);shovel.Tick(1);shovel.Tick(1);var vacuum=shovel.ActiveVacuum;var generated=vacuum.fillFrame.GetComponent<MeshFilter>().sharedMesh;foreach(var p in generated.vertices)if(!Inside(p))outside++;
 if(outside>0)throw new Exception("Packed grain protrudes beyond chamber: "+outside);
 var asset=UnityEngine.Object.Instantiate(generated);asset.name="LVL5 casing fitted grain preview";const string path="Assets/GrainPrototype/LVL5 fitted grain.asset";if(AssetDatabase.LoadAssetAtPath<Mesh>(path)==null)AssetDatabase.CreateAsset(asset,path);else {EditorUtility.CopySerialized(asset,AssetDatabase.LoadAssetAtPath<Mesh>(path));UnityEngine.Object.DestroyImmediate(asset);}
 tool.fillFrame.GetComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);tool.fillFrame.GetComponent<MeshRenderer>().sharedMaterial=tool.kernelMaterial;EditorUtility.SetDirty(tool.fillFrame.GetComponent<MeshFilter>());EditorUtility.SetDirty(tool.fillFrame.GetComponent<MeshRenderer>());
 }finally{if(preview!=null)UnityEngine.Object.DestroyImmediate(preview);}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(tool.gameObject.scene);EditorSceneManager.SaveScene(tool.gameObject.scene);return new{kernels=points.Count,spacing,verticesOutside=outside,shape=bounds.ToString()};
 }
}
